    private void btn2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btn2ActionPerformed
        String uN = username1.getText().trim();
        String pW = new String(password1.getPassword());

        if (uN.isEmpty() || pW.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Please enter both username and password.", "Error", JOptionPane.WARNING_MESSAGE);
            return;
        }

        try {

            Connection conn = dbconnection.getConnection();

            String sql = "SELECT * FROM tbl_admin WHERE uname= ? AND password= ?";
            PreparedStatement pst = conn.prepareStatement(sql);
            pst.setString(1, uN);
            pst.setString(2, pW);

            ResultSet rs = pst.executeQuery();

            if (rs.next()) {
                int adminID = rs.getInt("admin_id");

                UserSession.setUser(adminID, uN);
                JOptionPane.showMessageDialog(this, "Login Successful!");

                new admin_dashboard() .setVisible(true);
                this.dispose();

            } else {
                JOptionPane.showMessageDialog(this,"Invalid username or password",
                    "Dialog", JOptionPane.ERROR_MESSAGE);
            }
            conn.close();
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Error: "  + e.getMessage());
        }
    }//GEN-LAST:event_btn2ActionPerformed

